examples.template:
MonarchCalendarToolbar(
    {{title}},
    view: $view,
    views: [{{views.0|case}}, {{views.1|case}}, {{views.2|case}}, {{views.3|case}}],
    isTodayDisabled: {{todayDisabled}},
    onToday: {},
    onPrevious: {},
    onNext: {}
) {
    MonarchButton({{action.label}}, variant: {{action.variant|case}}, size: {{action.size|case}}) {}
}

examples.code:
MonarchCalendarToolbar(
    "November 2026",
    view: $view,
    views: [.day, .week, .month, .agenda],
    isTodayDisabled: true,
    onToday: {},
    onPrevious: {},
    onNext: {}
) {
    MonarchButton("New event", variant: .primary, size: .sm) {}
}

MonarchCalendarToolbar(
    "2 – 8 Nov 2026",
    view: $view,
    views: [.day, .week],
    isBusy: true,
    onToday: {},
    onPrevious: {},
    onNext: {},
    actions: {
        MonarchButton("New", systemImage: "plus", variant: .primary, size: .sm) {}
    }
)
